#include <vector>
#include <algorithm>
#include <cmath>

struct Point3D { float x, y, z; };

std::vector<size_t> GetNearestNeighborsSimplified(const std::vector<Point3D>& points, const Point3D& searchPoint, std::size_t k) {
    if (k == 0 || points.empty()) {
        return {};
    }
    k = std::min(k, points.size());

    // Create a vector of pairs: (squared_distance, index)
    std::vector<std::pair<float, size_t>> distances;
    distances.reserve(points.size());

    for (size_t i = 0; i < points.size(); ++i) {
        float dx = points[i].x - searchPoint.x;
        float dy = points[i].y - searchPoint.y;
        float dz = points[i].z - searchPoint.z;
        float squared_distance = dx * dx + dy * dy + dz * dz;
        distances.emplace_back(squared_distance, i);
    }

    // Partial sort to get the k smallest distances
    std::partial_sort(
        distances.begin(),
        distances.begin() + k,
        distances.end(),
        [](const auto& a, const auto& b) {
            return a.first < b.first;
        }
    );

    // Extract the indices
    std::vector<size_t> result;
    result.reserve(k);
    for (size_t i = 0; i < k; ++i) {
        result.push_back(distances[i].second);
    }

    return result;
}

